/* ============ A5 projects ============ */
const FOLDERS = { confluo: ['Confluo', 'Confluo/docs/plan/v2/demo'], latentskill: ['~/Research/ppb', '~/Research/latentskill（软链接）'], teamhub: ['team-hub'], hackathon: ['Hackathon'], quant: ['Auto Finance & Quant', 'Auto Finance & Quant/packages/datahub'], fhgs: ['FHGS Website/apps/web', 'FHGS Website/apps/stats'], surge: ['~/.config/surge'], tweet: ['Tweet Card'], other: ['~/Research/General', '~/Downloads', '~/Projects/Coffee'] };
PAGES.projects = () => {
  const L = sel({ project: null });
  const rows = projRows(L).filter((r) => r.st.n > 0).sort((a, b) => b.st.hours - a.st.hours);
  const selRow = rows.find((r) => r.p.id === S.proj.sel) || rows[0];
  if (!selRow) return tbar('项目习惯', '') + '<div class="content" id="content">' + filterRow() + empty('所选范围内没有会话') + '</div>';
  S.proj.sel = selRow.p.id;
  const p = selRow.p; const xs = selRow.xs; const st = selRow.st;
  const cmpRow = S.proj.cmp ? rows.find((r) => r.p.id === S.proj.cmp) : null;
  const overall = stats(L);
  const days = (arr) => new Set(arr.map((s) => s.d)).size || 1;
  const pts = rows.filter((r) => r.st.n >= 3).map((r) => ({ x: r.st.auto, y: r.st.fric, h: r.st.hours, id: r.p.id, name: r.p.name }));
  const reg = regress(pts); CUR.reg = reg; CUR.pts = pts;
  const xmax = Math.max(20, Math.ceil(Math.max(...pts.map((q) => q.x), 1) / 5) * 5), ymax = Math.max(15, Math.ceil(Math.max(...pts.map((q) => q.y), 1) / 5) * 5);
  const W = 430, H = 250, x0 = 32, y0 = 8, pw = W - x0 - 8, ph = H - y0 - 26;
  const sx = (v) => x0 + v / xmax * pw, sy = (v) => y0 + (1 - v / ymax) * ph;
  let sc = '';
  for (let v = 0; v <= xmax; v += 5) sc += '<line x1="' + sx(v) + '" x2="' + sx(v) + '" y1="' + y0 + '" y2="' + (y0 + ph) + '" stroke="var(--hair)"/><text x="' + sx(v) + '" y="' + (y0 + ph + 16) + '" text-anchor="middle">' + v + '×</text>';
  for (let v = 0; v <= ymax; v += 5) sc += '<line x1="' + x0 + '" x2="' + (x0 + pw) + '" y1="' + sy(v) + '" y2="' + sy(v) + '" stroke="var(--hair)"/><text x="' + (x0 - 6) + '" y="' + (sy(v) + 3.5) + '" text-anchor="end">' + v + '%</text>';
  if (reg) { const xa = Math.min(...pts.map((q) => q.x)), xb = Math.max(...pts.map((q) => q.x)); sc += '<line x1="' + sx(xa).toFixed(1) + '" y1="' + sy(clamp(reg.a + reg.b * xa, 0, ymax)).toFixed(1) + '" x2="' + sx(xb).toFixed(1) + '" y2="' + sy(clamp(reg.a + reg.b * xb, 0, ymax)).toFixed(1) + '" stroke="var(--h2)" stroke-width="2" stroke-linecap="round"/>'; }
  pts.slice().sort((a, b) => b.h - a.h).forEach((q) => { const r = 4 + Math.sqrt(q.h) * 2.1; const on = q.id === p.id || (cmpRow && q.id === cmpRow.p.id); sc += '<circle cx="' + sx(q.x).toFixed(1) + '" cy="' + sy(q.y).toFixed(1) + '" r="' + r.toFixed(1) + '" fill="' + (on ? 'var(--ink-1)' : 'var(--h1)') + '" stroke="' + (on ? 'var(--ink-1)' : 'var(--h3)') + '" stroke-width="1.5" data-tf="pt|' + q.id + '" data-act="pickProject" data-p="' + q.id + '" style="cursor:pointer"/><text x="' + (sx(q.x) + r + 4).toFixed(1) + '" y="' + (sy(q.y) + 4).toFixed(1) + '" font-family="var(--sans)" font-size="11" fill="' + (on ? 'var(--ink-1)' : 'var(--ink-2)') + '" font-weight="' + (on ? 700 : 400) + '">' + esc(q.name) + '</text>'; });
  sc += '<text x="' + (x0 + pw) + '" y="' + (y0 + ph - 6) + '" text-anchor="end" font-family="var(--sans)">自主比 →</text><text x="' + (x0 + 4) + '" y="' + (y0 + 12) + '" font-family="var(--sans)">↑ 摩擦率</text>';
  const tableRows = S.proj.group === 'folder'
    ? rows.flatMap((r) => FOLDERS[r.p.id].map((f, i, arr) => { const share = arr.length === 1 ? 1 : i === 0 ? 0.72 : 0.28 / (arr.length - 1); return { r, f, n: Math.max(1, Math.round(r.st.n * share)), h: r.st.hours * share }; }))
    : rows.map((r) => ({ r, f: null, n: r.st.n, h: r.st.hours }));
  const cmpA = cmpRow ? cmpRow.st : overall; const cmpXs = cmpRow ? cmpRow.xs : L; const cmpName = cmpRow ? cmpRow.p.name : '整体';
  const metrics = [['平均会话时长', st.hours * 60 / Math.max(1, st.n), cmpA.hours * 60 / Math.max(1, cmpA.n), (v) => Math.round(v) + 'm'], ['每会话消息', st.per, cmpA.per, (v) => f1(v)], ['自主比', st.auto, cmpA.auto, (v) => f1(v) + '×'], ['要求验证', st.verify, cmpA.verify, (v) => Math.round(v) + '%'], ['摩擦率', st.fric, cmpA.fric, (v) => f1(v) + '%'], ['日均会话', st.n / days(xs), cmpA.n / days(cmpXs), (v) => f1(v)]];
  const split = selRow.split; const splitTot = split.reduce((a, b) => a + b, 0) || 1;
  const pp = selRow.pers;
  return tbar('项目习惯', rows.length + ' 个项目 · ' + f1(overall.hours) + ' 小时 · 按协作时长排序', '<button type="button" class="btn' + (S.proj.cmpMode ? ' p' : '') + '" data-act="projCompare">' + (S.proj.cmpMode ? '退出对比' : '对比两个项目') + '</button><button type="button" class="btn ai" data-act="projRule">' + ic('spark', 14) + '为此项目起草规则</button>') +
    '<div class="content" id="content">' + filterRow('<span class="cap">聚合</span><div class="seg" role="group" aria-label="聚合方式"><button type="button" data-act="projGroup" data-v="project" class="' + (S.proj.group === 'project' ? 'on' : '') + '">按项目</button><button type="button" data-act="projGroup" data-v="folder" class="' + (S.proj.group === 'folder' ? 'on' : '') + '">按文件夹</button></div>') +
    '<div class="proj"><div class="stack"><div class="card pad"><div class="scroll-x"><table class="tbl"><thead><tr><th>' + (S.proj.group === 'folder' ? '文件夹' : '项目') + '</th><th style="text-align:right">会话</th><th style="text-align:right">时长</th><th>Agent 构成</th><th style="text-align:right">此处人格</th></tr></thead><tbody>' +
    tableRows.map((t) => { const r = t.r; const on = r.p.id === p.id, on2 = cmpRow && r.p.id === cmpRow.p.id; const tot2 = r.split.reduce((a, b) => a + b, 0) || 1; return '<tr class="click' + (on || on2 ? ' sel' : '') + '" data-act="pickProject" data-p="' + r.p.id + '"><td style="min-width:0"><div style="font-weight:600;font-size:12.5px">' + esc(t.f || r.p.name) + (on2 ? ' <span class="bdg">B</span>' : '') + '</div><div class="mono cap" style="font-size:10.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:200px">' + esc(t.f ? '归入 ' + r.p.name : r.p.path) + '</div></td><td class="mono" style="text-align:right">' + t.n + '</td><td class="mono" style="text-align:right">' + f1(t.h) + 'h</td><td><div style="display:flex;height:8px;gap:1px;border-radius:2px;overflow:hidden;width:92px">' + r.split.map((v, j) => v ? '<span style="width:' + (v / tot2 * 100) + '%;background:' + AG[j].c + '" data-tip="' + AG[j].name + '：' + v + ' 个会话"></span>' : '').join('') + '</div></td><td class="mono" style="text-align:right;font-weight:' + (r.pers.ok && r.pers.code !== 'DIMV' ? 700 : 500) + ';letter-spacing:.04em;color:' + (r.pers.ok ? 'var(--ink-1)' : 'var(--ink-3)') + '">' + (r.pers.ok ? r.pers.code : '—') + '</td></tr>'; }).join('') + '</tbody></table></div><div class="cap" style="font-size:11px;margin-top:8px">按项目时以 git 根目录归并子文件夹 · 「—」表示样本少于 8 个会话</div></div>' +
    '<div class="card pad"><div class="hd"><div class="grow"><span class="ct">跨项目对比</span><span class="cap">面积 = 时长 · 灰线为最小二乘拟合' + (reg ? '（r = ' + f1(reg.r) + '，n = ' + reg.n + '）' : '') + '</span></div></div><svg class="chart" viewBox="0 0 ' + W + ' ' + H + '" role="img" aria-label="各项目自主比与摩擦率散点图">' + sc + '</svg><div class="cap" style="font-size:11.5px;margin-top:6px;line-height:1.5">' + (reg ? '自主比每高 1×，摩擦率平均高 ' + f1(reg.b) + ' 个百分点。悬停看各项目在线的上方还是下方。' : '项目太少，无法拟合。') + '</div></div></div>' +
    '<div class="stack"><div class="card pad"><div class="row" style="gap:12px;flex-wrap:wrap"><span style="width:36px;height:36px;border-radius:9px;background:var(--sunken);display:grid;place-items:center">' + ic('projects', 18) + '</span><div style="flex:1;min-width:200px"><div class="row" style="align-items:baseline;gap:10px;flex-wrap:wrap"><h2 class="serif" style="margin:0;font-size:22px">' + esc(p.name) + '</h2><span class="mono cap">' + esc(p.path) + ' · git: ' + esc(p.git) + '</span></div><div class="row" style="gap:6px;margin-top:4px;flex-wrap:wrap">' + p.tags.map((t) => '<span class="tag">' + t + '</span>').join('') + '</div></div><button type="button" class="btn" data-act="finder">在 Finder 中显示</button><button type="button" class="btn" data-act="openAgents">打开 AGENTS.md</button></div>' +
    '<div class="row" style="margin-top:12px;padding:8px 10px;border-radius:8px;background:var(--sunken);font-size:12.5px;color:var(--ink-2);flex-wrap:wrap;gap:6px">' + ic('persona', 14) + (pp.ok ? '在这个项目里你是 <b class="mono" style="color:var(--ink-1);letter-spacing:.04em">' + pp.code + '</b><b style="color:var(--ink-1)">' + pp.zh + '</b>' + (personaNow().ok && personaNow().code !== pp.code ? '，和整体（' + personaNow().code + ' ' + personaNow().zh + '）不同' : '，和整体一致') + '。' : '这个项目的会话少于 8 个，暂不判断人格。') + '</div></div>' +
    '<div class="two" style="grid-template-columns:minmax(0,1fr) 262px"><div class="card pad"><div class="hd"><div class="grow"><span class="ct">此项目 vs ' + esc(cmpName) + '</span></div><span class="row cap" style="font-size:11px;gap:10px"><span class="row" style="gap:4px"><span style="width:10px;height:8px;border-radius:2px;background:var(--ink-1)"></span>' + esc(p.name) + '</span><span class="row" style="gap:4px"><span style="width:10px;height:8px;border-radius:2px;background:var(--h2)"></span>' + esc(cmpName) + '</span></span></div><div class="col" style="gap:8px">' + metrics.map((m) => { const mx = Math.max(m[1], m[2]) || 1; return '<div style="display:grid;grid-template-columns:92px minmax(0,1fr) 100px;gap:10px;align-items:center"><span style="font-size:12px;color:var(--ink-2)">' + m[0] + '</span><span class="col" style="gap:2px"><span style="height:7px;width:' + (m[1] / mx * 100) + '%;border-radius:0 3px 3px 0;background:var(--ink-1)"></span><span style="height:7px;width:' + (m[2] / mx * 100) + '%;border-radius:0 3px 3px 0;background:var(--h2)"></span></span><span class="mono" style="font-size:11px;text-align:right;color:var(--ink-2)"><b style="color:var(--ink-1)">' + m[3](m[1]) + '</b> / ' + m[3](m[2]) + '</span></div>'; }).join('') + '</div>' + (S.proj.cmpMode && !cmpRow ? '<div class="cap" style="margin-top:8px">在左侧表格或散点图里点另一个项目作为 B</div>' : '') + '</div>' +
    '<div class="card pad"><div class="ct" style="margin-bottom:8px">Agent 分工</div><div style="display:flex;height:12px;gap:2px;border-radius:3px;overflow:hidden">' + split.map((v, j) => v ? '<span style="width:' + (v / splitTot * 100) + '%;background:' + AG[j].c + '"></span>' : '').join('') + '</div><div class="col" style="gap:6px;margin-top:10px">' + split.map((v, j) => v ? '<div class="row" style="font-size:12px"><span style="width:10px;height:10px;border-radius:2px;background:' + AG[j].c + '"></span><span style="flex:1">' + AG[j].name + '</span><span class="mono">' + Math.round(v / splitTot * 100) + '%</span></div>' : '').join('') + '</div></div></div>' +
    '<div class="card pad"><div class="hd"><div class="grow"><span class="ct">识别到的工作流</span><span class="cap">出现在 ' + Math.max(1, Math.round(xs.length * 0.61)) + ' / ' + xs.length + ' 个会话 · 支持度 61%</span></div></div><div class="row" style="flex-wrap:wrap;gap:8px">' + p.flow.map((f, i) => '<span class="col" style="gap:0;padding:6px 12px;border-radius:9px;border:1px solid var(--line);background:var(--bg)"><b style="font-size:12.5px">' + f[0] + '</b><span class="mono cap" style="font-size:10px">' + esc(f[1]) + '</span></span>' + (i < p.flow.length - 1 ? ic('arrow', 14, 'color:var(--ink-4)') : '')).join('') + '</div><div class="row" style="margin-top:10px;flex-wrap:wrap"><span style="flex:1;min-width:200px;font-size:12px;color:var(--ink-2)">固定成一个 Skill 后，每次可少说约 4 条指令。</span><button type="button" class="btn sm ai" data-act="flowToStudio">' + ic('spark', 12) + '封装为 Skill</button></div></div>' +
    '<div class="card pad"><div class="hd"><div class="grow"><span class="ct">规则与配置覆盖</span><span class="cap">扫描 AGENTS.md、.claude、.codex、.gemini</span></div></div><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(110px,1fr));gap:8px">' + p.cover.map((c) => '<div style="border-radius:9px;border:1px solid var(--line);padding:8px 10px"><div class="row" style="gap:5px;font-size:12px;font-weight:600">' + ic(c[3] ? 'okc' : 'minus', 13, 'color:' + (c[3] ? 'var(--good)' : 'var(--ink-4)')) + c[0] + '</div><div class="mono" style="font-size:16px;font-weight:600">' + c[1] + '</div><div class="cap" style="font-size:11px">' + c[2] + '</div></div>').join('') + '</div><div class="row" style="margin-top:10px;padding:7px 10px;border-radius:8px;background:var(--sunken);flex-wrap:wrap">' + ic('bolt', 15, 'color:var(--ai)') + '<span style="flex:1;min-width:200px;font-size:12px;color:var(--ink-2)">建议：' + esc(p.tip) + '</span><button type="button" class="btn sm" data-act="openRec" data-id="' + p.rec + '">查看建议</button></div></div></div></div></div>';
};
TIPS.pt = (id) => { const q = (CUR.pts || []).find((x) => x.id === id); if (!q) return ''; const reg = CUR.reg; const res = reg ? q.y - (reg.a + reg.b * q.x) : 0; return '<b>' + esc(q.name) + '</b>\n自主比 ' + f1(q.x) + '× · 摩擦率 ' + f1(q.y) + '% · ' + f1(q.h) + ' 小时' + (reg ? '\n' + (res >= 0 ? '比同等自主度预期高 ' : '比同等自主度预期低 ') + f1(Math.abs(res)) + ' 个百分点' + (res >= 0 ? '，适合先加护栏' : '，可以作为参照') : ''); };
Object.assign(ACT, {
  pickProject: (el) => { const id = el.dataset.p; if (S.proj.cmpMode) { if (id !== S.proj.sel) S.proj.cmp = id; } else S.proj.sel = id; if (S.route !== 'projects') go('projects'); else render(); },
  projCompare: () => { if (S.proj.cmpMode) { S.proj.cmpMode = false; S.proj.cmp = null; } else { S.proj.cmpMode = true; S.proj.cmp = ''; toast('在左侧表格或散点图里点另一个项目作为 B'); } render(); },
  projGroup: (el) => { S.proj.group = el.dataset.v; render(); },
  finder: () => toast('已在 Finder 中显示（演示）：' + PJI[S.proj.sel].path),
  openAgents: () => toast('已用默认编辑器打开 AGENTS.md（演示，应用内不改写文件）'),
  flowToStudio: () => { const p = PJI[S.proj.sel]; S.studio.type = 'Skill'; S.studio.goal = '把 ' + p.name + ' 里反复出现的工作流做成一个 Skill：' + p.flow.map((f) => f[0]).join(' → ') + '。'; S.studio.from = 'A5 识别到的工作流 · ' + p.name; S.studio.run = null; go('studio'); },
  projRule: () => { const p = PJI[S.proj.sel]; S.studio.type = '规则'; S.studio.goal = '为 ' + p.name + ' 起草一段 AGENTS.md 规则，覆盖最常见的纠偏：' + Object.keys(p.fric).slice(0, 2).join('、') + '。'; S.studio.from = 'A5 项目习惯 · ' + p.name; S.studio.run = null; go('studio'); }
});

